using Xunit;
using Microsoft.Extensions.DependencyInjection;
using Moq;
using System;
using Microsoft.SemanticKernel.Plugins.Web;

namespace WebServiceCollectionExtensionsTests
{
    public class AddBingTextSearchTests
    {
        [Fact]
        public void AddsBingTextSearch_WithNullOptions_CallsGetService()
        {
            // Arrange
            var services = new ServiceCollection();
            var serviceProviderMock = new Mock<IServiceProvider>();
            var options = new BingTextSearchOptions();

            // Setup GetService to return options when called
            serviceProviderMock
                .Setup(sp => sp.GetService<BingTextSearchOptions>())
                .Returns(options);

            // Build a service provider from the service collection
            var serviceProvider = services.BuildServiceProvider();

            // Act
            services.AddBingTextSearch("testApiKey");

            // Create a scope to resolve services
            var scope = services.BuildServiceProvider().CreateScope();
            var sp = scope.ServiceProvider;

            // Call the registered factory manually to simulate the behavior
            var factory = services[0] as ServiceDescriptor;
            var factoryDelegate = factory?.ImplementationFactory;
            Assert.NotNull(factoryDelegate);

            var textSearchInstance = factoryDelegate(sp, null);

            // Assert
            Assert.IsType<BingTextSearch>(textSearchInstance);
            var bingTextSearch = textSearchInstance as BingTextSearch;
            Assert.NotNull(bingTextSearch);
            Assert.Equal("testApiKey", bingTextSearch.ApiKey);
        }
    }
}
```

